// The sources the radar reads each morning. Add or remove a line to change them.
// Checked 2026-11-24. Product Hunt was dropped: its feed carries no description to grade.
// TechCrunch was dropped: it refuses automated feed readers (403), and the radar does not work around a block. Anthropic publishes no RSS feed, so Claude news goes in through the form.
return [
  { url: 'https://openai.com/news/rss.xml' },
  { url: 'https://blog.google/technology/ai/rss/' },
  { url: 'https://www.microsoft.com/en-us/microsoft-365/blog/feed/' },
  { url: 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml' }, // covers Anthropic, Microsoft and others
  { url: 'https://www.zapier.com/blog/feeds/latest/' },                       // automation tools for non-engineers
  // Added 2026-11-25: product release notes. The first run showed news feeds are mostly not tools (16 of 20 rejected).
  { url: 'https://workspaceupdates.googleblog.com/feeds/posts/default' },
].map(json => ({ json }));

// Keep only fresh items: at most 7 days old, and the 5 newest per source.
// Also note which feeds gave nothing fresh (failed, or just quiet this week), so the page can say so.
const SOURCES = { 'openai.com': 'OpenAI', 'blog.google': 'Google', 'microsoft.com': 'Microsoft 365', 'theverge.com': 'The Verge', 'zapier.com': 'Zapier', 'googleblog.com': 'Google Workspace' };
const MAX_AGE_DAYS = 7, PER_SOURCE = 5;
// n8n's code box has no URL class, so the host is read with a pattern.
const sourceOf = (link) => {
  const m = /^https?:\/\/([^\/?#:@]+)/i.exec(String(link));
  if (!m) return null;
  const h = m[1].toLowerCase().replace(/^www\./, '');
  return SOURCES[h] || SOURCES[h.split('.').slice(-2).join('.')] || h;
};
const strip = (s) => String(s || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

const now = Date.now(), bySource = {};
for (const { json: it } of $input.all()) {
  const source = it.link && sourceOf(it.link);
  if (!source || !it.title) continue;                       // a failed feed gives an item with no link
  const t = Date.parse(it.isoDate || it.pubDate || '');
  if (isNaN(t) || now - t > MAX_AGE_DAYS * 864e5 || t - now > 2 * 864e5) continue;   // too old, or a wrong date far in the future
  (bySource[source] ||= []).push({
    title: strip(it.title).slice(0, 200), link: it.link,
    snippet: strip(it.contentSnippet || it.content || it.summary).slice(0, 1500),
    date: new Date(t).toISOString(), source,
  });
}
const feeds_failed = Object.values(SOURCES).filter(s => !bySource[s]);
return Object.values(bySource)
  .flatMap(list => list.sort((a, b) => b.date.localeCompare(a.date)).slice(0, PER_SOURCE))
  .map(json => ({ json: { ...json, feeds_failed } }));

// Drop items the radar has already dealt with: links that already have a card,
// and links Claude already judged not relevant. The list lives in cards.json,
// so an item is only marked seen after it was graded successfully.
const saved = JSON.parse(Buffer.from($input.first().json.content, 'base64').toString('utf8'));
const seen = new Set([...(saved.cards || []).map(c => c.url), ...(saved.seen || [])]);
return $('Keep recent').all().filter(i => !seen.has(i.json.link)).map(i => ({ json: i.json }));

// The form accepts any text. Only fetch real public web links.
// n8n's code box has no URL class, so the link is checked with a pattern.
const form = $input.first().json;
const link = String(form.link || form['Tool link'] || '').trim();
const m = /^https?:\/\/([^\/?#:@\s]+)(:\d+)?([\/?#]\S*)?$/i.exec(link);
if (!m) throw new Error('That is not a link. Paste the full address, starting with https://');
const host = m[1].toLowerCase();
const isPrivate = host === 'localhost' || !host.includes('.') || host.endsWith('.local') || host.endsWith('.internal') ||
  /^(127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.|0\.)/.test(host) || host.includes('[');
if (isPrivate) throw new Error('Only public web links can be graded.');
return [{ json: { link, host, pasted: String(form.pasted || form['Announcement text (optional)'] || '').slice(0, 3000) } }];

// Turn the fetched page into the same shape a feed item has.
const src = $('Check link').first().json;
const html = String($input.first().json.data || '');
const titleMatch = html.match(/<title[^>]*>([^<]*)<\/title>/i);
const text = html.replace(/<(script|style|noscript)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]*>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim();
const snippet = (src.pasted ? src.pasted + ' ' : '') + text.slice(0, 3000);
if (snippet.trim().length < 80) throw new Error('Could not read that page. Paste the announcement text into the second box and try again.');
return [{ json: {
  title: (titleMatch ? titleMatch[1].trim() : src.host).slice(0, 200),
  link: src.link, snippet: snippet.slice(0, 3500), date: new Date().toISOString(), source: 'Submitted', feeds_failed: [],
} }];

// Read Claude's answers. Keep only well-formed, relevant cards; count the rest.
const AUDIENCES = ['Brand & marketing', 'Sales', 'Supply chain & brewery', 'Finance', 'Internal comms & HR'];
const VERDICTS = ['Try now', 'Watch', 'Skip'];
const asked = $('Build request').all();
const answers = $input.all();
const newCards = [], notRelevantLinks = []; let malformed = 0;

answers.forEach(({ json: res }, i) => {
  const src = asked[i].json;
  let a;
  try {
    const text = res.content.find(b => b.type === 'text').text;
    a = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  } catch { malformed++; return; }                          // API error or a reply that is not JSON
  if (a.relevant !== true) { notRelevantLinks.push(src.link); return; }
  const audiences = (Array.isArray(a.audiences) ? a.audiences : []).filter(x => AUDIENCES.includes(x)).slice(0, 3);
  const text = (v, n) => typeof v === 'string' && v.trim() ? v.trim().slice(0, n) : null;
  const card = {
    url: src.link, title: text(a.title, 120), what: text(a.what, 300), audiences,
    try_for: text(a.try_for, 250), verdict: a.verdict, impact: [1, 2, 3].includes(a.impact) ? a.impact : 1, why: text(a.why, 300),
    catch: text(a.catch, 300), data_caution: text(a.data_caution, 300),
    source: src.source, date: src.date, original_title: src.title,
    graded_at: new Date().toISOString(), model: src.model,
  };
  const complete = card.title && card.what && card.try_for && card.catch && audiences.length && VERDICTS.includes(card.verdict);
  if (!complete) { malformed++; return; }
  newCards.push(card);
});
// Unreadable answers are not marked seen, so they are tried again on the next run.
return [{ json: { newCards, notRelevantLinks, notRelevant: notRelevantLinks.length, malformed, feeds_failed: asked[0] ? asked[0].json.feeds_failed : [], fromForm: asked[0] && asked[0].json.source === 'Submitted' } }];

// Add today's cards to the saved list. A card for a link we already have replaces the old one.
const run = $('Make cards').first().json;
const file = $input.first().json;
const old = JSON.parse(Buffer.from(file.content, 'base64').toString('utf8'));
const fresh = new Set(run.newCards.map(c => c.url));
const cards = [...run.newCards, ...(old.cards || []).filter(c => !fresh.has(c.url))]
  .sort((a, b) => String(b.date).localeCompare(String(a.date))).slice(0, 300);
const seen = [...new Set([...(old.seen || []), ...run.notRelevantLinks])].slice(-1000);   // links judged not relevant
const out = {
  updated: new Date().toISOString(),
  feeds_failed: run.fromForm ? (old.feeds_failed || []) : run.feeds_failed,   // a form run reads no feeds
  cards, seen,
};
return [{ json: {
  content: JSON.stringify(out, null, 2) + '\n', added: run.newCards.length, total: cards.length,
  message: `Radar: +${run.newCards.length} card(s), ${run.notRelevant} not relevant, ${run.malformed} unreadable`,
} }];
